{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "It would require local education agencies and public charter schools to provide feminine hygiene products, such as tampons, panty liners, menstrual cups, and sanitary napkins, at no charge for student use. These products must be available in all women's and girls' bathrooms, all locker rooms, and with the school nurse in eligible school buildings, which are defined as senior high schools.",
      "rationale": "Read together, these sentences convey coverage of public senior high schools, including public charter schools. The statutory definition cross-reference is not essential here."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "feminine hygiene products, such as tampons, panty liners, menstrual cups, and sanitary napkins",
      "rationale": "The summary lists the specified examples but omits the broader definition covering products or materials for menstruation or other genital-tract secretions."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "It would require local education agencies and public charter schools to provide feminine hygiene products, such as tampons, panty liners, menstrual cups, and sanitary napkins, at no charge for student use. These products must be available in all women's and girls' bathrooms, all locker rooms, and with the school nurse in eligible school buildings, which are defined as senior high schools. Bathrooms and locker rooms designated for staff or teacher use are excluded from this requirement.",
      "rationale": "The summary conveys the responsible entities, free provision, required locations, and staff-use exception, but omits the limitation to school buildings where instruction is provided."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "at no charge for student use",
      "rationale": "This conveys that the products provided under the requirement are designated for students."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The department of education may provide guidance and policies to help schools comply.",
      "rationale": "The summary conveys the department's discretionary authority to provide compliance policies and guidance, using schools as shorthand for the covered education entities and their governing bodies."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The act would take effect July 1, 2025.",
      "rationale": "The effective date is stated accurately."
    }
  ]
}
